{
  "application": "ppt-generation",
  "case_id": "case-openrouter-stats",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 7,
    "audience": "LLM industry professionals (R&D, product, investment)",
    "tone": "data-forward, engaging, professional"
  },
  "brief": {
    "title": "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter",
    "one_liner": "Based on real usage data from millions of OpenRouter users, this deck reveals the competitive landscape and emerging trends in today's LLM market.",
    "goal": "Help the audience understand which models are most popular in real-world usage, how market share is distributed, which newcomers are rising fast, and what these patterns tell us about industry trends."
  },
  "slides": [
    {
      "id": "title",
      "title": "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter",
      "objective": "Cover slide showcasing the data source (OpenRouter Rankings, latest week of March 2025) and the headline metric: over 26T tokens processed this week."
    },
    {
      "id": "top-models",
      "title": "This Week's Top 10 Models",
      "objective": "Present the 10 most popular models this week using a table or bar chart, including model name, provider, token usage, and week-over-week change. Highlight that Xiaomi's MiMo-V2-Pro tops the list with 3.96T tokens."
    },
    {
      "id": "market-share",
      "title": "Provider Market Share Breakdown",
      "objective": "Use a pie chart or bar chart to show token share by provider. Xiaomi leads at 25.9%, followed by Google at 11.8%, Anthropic at 11.0%, MiniMax at 8.5%, and OpenAI at 7.9%. Note that provider-level market share figures represent share of the total market across all models and apps (including those outside the top 10), so individual provider volumes may differ from summing top-10 model tokens. Emphasize the rise of Chinese providers, whose combined share exceeds 54%."
    },
    {
      "id": "trends",
      "title": "Shifts in the Market Landscape",
      "objective": "Illustrate the current market dynamics and key competitive shifts: (1) Chinese models (Xiaomi, Stepfun, DeepSeek, MiniMax, Zhipu) now hold over 54% combined market share on this international platform; (2) Anthropic's growth has stalled despite maintaining two models in the top 10; (3) Flash/Turbo 'fast and affordable' variants far outpace flagship models in real-world usage. Reference the weekly token usage trend chart showing growth from ~2T to ~26T to underscore the rapidly expanding market."
    },
    {
      "id": "rising-stars",
      "title": "This Week's Rising Stars: Fastest-Growing Models",
      "objective": "Showcase the fastest-growing models: MiniMax M2.7 (+253%), Xiaomi MiMo-V2-Pro (+165%), Cline (+128%). Analyze the drivers behind their surge."
    },
    {
      "id": "app-ecosystem",
      "title": "App Ecosystem: Who's Calling These Models",
      "objective": "Present the top apps by usage: OpenClaw (829B tokens/day), Kilo Code, Claude Code, Cline. Analyze the trend of AI coding assistants becoming the largest usage category."
    },
    {
      "id": "takeaways",
      "title": "Key Insights and Industry Implications",
      "objective": "Summarize 3–4 core takeaways: (1) Chinese models now hold a dominant share in the global market; (2) AI coding agents are the single largest LLM consumption scenario; (3) the model market is highly fragmented with no outright winner; (4) affordable and fast models (Flash/Turbo variants) far outpace flagship models in usage."
    }
  ]
}

