            --small-size: clamp(0.55rem, 0.9vw, 0.8rem);
            --data-size: clamp(0.55rem, 0.85vw, 0.75rem);
            --slide-padding: clamp(1rem, 3vw, 3rem);
            --content-gap: clamp(0.4rem, 1.5vw, 1.5rem);
            --element-gap: clamp(0.2rem, 0.8vw, 0.75rem);
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE RESET
           =========================================== */
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body { height: 100%; overflow-x: hidden; }
        html { scroll-snap-type: y mandatory; scroll-behavior: smooth; }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(95vw, 1200px);
            max-height: min(85vh, 750px);
        }

        .feature-list, .bullet-list { gap: clamp(0.4rem, 1vh, 1rem); }
        .feature-list li, .bullet-list li { font-size: var(--body-size); line-height: 1.4; }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        img, .image-container { max-width: 100%; max-height: min(50vh, 400px); object-fit: contain; }

        /* === RESPONSIVE BREAKPOINTS === */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.6rem, 1.1vw, 0.85rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.55rem, 1vw, 0.8rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL SLIDE STYLES
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
        }

        .slide {
            background: var(--bg-primary);
        }

        /* Subtle grid pattern on all slides */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(0, 229, 255, 0.02) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 229, 255, 0.02) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }

        .slide-content { position: relative; z-index: 1; }

        /* Slide number */
        .slide-number {
            position: absolute;
            top: clamp(0.5rem, 2vw, 1.5rem);
            left: clamp(0.5rem, 2vw, 1.5rem);
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            z-index: 2;
        }

        /* Source badge */
        .source-badge {
            position: absolute;
            bottom: clamp(0.5rem, 1.5vw, 1rem);
            right: clamp(0.5rem, 2vw, 1.5rem);
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.7vw, 0.65rem);
            color: var(--text-muted);
            background: rgba(0, 229, 255, 0.05);
            border: 1px solid var(--border-subtle);
            padding: clamp(0.15rem, 0.3vw, 0.3rem) clamp(0.3rem, 0.8vw, 0.6rem);
            border-radius: 4px;
            z-index: 2;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.12s; }
        .reveal:nth-child(3) { transition-delay: 0.19s; }
        .reveal:nth-child(4) { transition-delay: 0.26s; }
        .reveal:nth-child(5) { transition-delay: 0.33s; }
        .reveal:nth-child(6) { transition-delay: 0.4s; }
        .reveal:nth-child(7) { transition-delay: 0.47s; }
        .reveal:nth-child(8) { transition-delay: 0.54s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity 0.5s var(--ease-out-expo), transform 0.5s var(--ease-out-expo);
        }
        .slide.visible .reveal-scale {
            opacity: 1;
            transform: scale(1);
        }

        @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 20px rgba(0, 229, 255, 0.15); }
            50% { box-shadow: 0 0 40px rgba(0, 229, 255, 0.3); }
        }

        @keyframes float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-6px); }
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-orange));
            z-index: 9999;
            transition: width 0.3s ease;
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 1.5vw, 1.2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 9998;
        }
        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.15);
            border: 1px solid rgba(255, 255, 255, 0.1);
            cursor: pointer;
            transition: all 0.3s ease;
        }
        .nav-dot.active {
            background: var(--accent-cyan);
            box-shadow: 0 0 8px rgba(0, 229, 255, 0.4);
            transform: scale(1.3);
        }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 229, 255, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(255, 107, 53, 0.06) 0%, transparent 50%),
                radial-gradient(ellipse at 50% 50%, rgba(124, 77, 255, 0.04) 0%, transparent 60%),
                var(--bg-primary);
        }

        .title-slide .slide-content {
            align-items: center;
            text-align: center;
            justify-content: center;
            gap: clamp(0.5rem, 2vw, 1.5rem);
        }

        .title-metric {
            font-family: var(--font-mono);
            font-size: clamp(2.5rem, 8vw, 6rem);
            font-weight: 700;
            background: linear-gradient(135deg, var(--accent-cyan), var(--accent-cyan) 40%, var(--accent-orange));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            line-height: 1.1;
            letter-spacing: -0.02em;
        }

        .title-metric-label {
            font-family: var(--font-body);
            font-size: clamp(0.7rem, 1.5vw, 1.1rem);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.15em;
            font-weight: 500;
        }

        .title-heading {
            font-family: var(--font-display);
            font-size: clamp(1.2rem, 3.5vw, 2.8rem);
            font-weight: 800;
            color: var(--text-primary);
            line-height: 1.15;
            max-width: 900px;
        }

        .title-sub {
            font-family: var(--font-body);
            font-size: clamp(0.65rem, 1.2vw, 0.95rem);
            color: var(--text-secondary);
            max-width: 700px;
            line-height: 1.5;
        }

        .title-source-tag {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            font-family: var(--font-mono);
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            color: var(--accent-cyan);
            background: rgba(0, 229, 255, 0.08);
            border: 1px solid var(--border-accent);
            padding: clamp(0.2rem, 0.4vw, 0.4rem) clamp(0.4rem, 1vw, 0.8rem);
            border-radius: 20px;
            margin-top: clamp(0.3rem, 1vw, 0.8rem);
        }

        /* Decorative corner accent */
        .corner-accent {
            position: absolute;
            width: clamp(60px, 10vw, 150px);
            height: clamp(60px, 10vw, 150px);
            border: 2px solid rgba(0, 229, 255, 0.1);
            z-index: 0;
        }
        .corner-accent.tl { top: clamp(1rem, 3vw, 2.5rem); left: clamp(1rem, 3vw, 2.5rem); border-right: none; border-bottom: none; }
        .corner-accent.br { bottom: clamp(1rem, 3vw, 2.5rem); right: clamp(1rem, 3vw, 2.5rem); border-left: none; border-top: none; }

        /* ===========================================
           SLIDE 2: TOP 10 MODELS TABLE
           =========================================== */
        .table-slide .slide-content {
            justify-content: flex-start;
            padding-top: clamp(1.5rem, 4vw, 3rem);
        }

        .slide-title {
            font-family: var(--font-display);
            font-size: clamp(1rem, 2.8vw, 2rem);
            font-weight: 800;
            color: var(--text-primary);
            margin-bottom: clamp(0.3rem, 1vw, 0.8rem);
        }

        .slide-subtitle {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-bottom: clamp(0.5rem, 1.5vw, 1rem);
        }

        .data-table-wrapper {
            width: 100%;
            max-width: 1100px;
            overflow: hidden;
        }

        .data-table {
            width: 100%;
            border-collapse: separate;
            border-spacing: 0 clamp(0.15rem, 0.4vw, 0.3rem);
            font-size: var(--data-size);
        }

        .data-table thead th {
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.7vw, 0.6rem);
            font-weight: 600;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            padding: clamp(0.2rem, 0.5vw, 0.4rem) clamp(0.3rem, 0.8vw, 0.6rem);
            text-align: left;
            border-bottom: 1px solid var(--border-accent);
        }

        .data-table thead th:nth-child(4),
        .data-table thead th:nth-child(5) { text-align: right; }

        .data-table tbody tr {
            background: rgba(255, 255, 255, 0.02);
            transition: background 0.2s;
        }

        .data-table tbody tr:hover {
            background: rgba(0, 229, 255, 0.04);
        }

        .data-table td {
            padding: clamp(0.25rem, 0.5vw, 0.45rem) clamp(0.3rem, 0.8vw, 0.6rem);
            vertical-align: middle;
        }

        .data-table td:nth-child(4),
        .data-table td:nth-child(5) { text-align: right; font-family: var(--font-mono); }

        .rank-cell {
            font-family: var(--font-mono);
            font-weight: 700;
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            color: var(--accent-cyan);
            width: 30px;
        }

        .rank-cell.top3 { color: var(--accent-orange); }

        .model-name {
            font-weight: 600;
            color: var(--text-primary);
            font-size: clamp(0.55rem, 0.9vw, 0.78rem);
        }

        .provider-name {
            font-size: clamp(0.5rem, 0.75vw, 0.65rem);
            color: var(--text-secondary);
        }

        .provider-chinese {
            color: var(--accent-orange);
        }

        .token-cell {
            font-weight: 600;
            color: var(--text-primary);
        }

        .wow-positive { color: var(--accent-green); font-weight: 600; }
        .wow-negative { color: var(--accent-pink); font-weight: 600; }
        .wow-neutral { color: var(--text-muted); }

        /* Bar indicator */
        .bar-indicator {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.6vw, 0.5rem);
        }

        .bar-bg {
            flex: 1;
            height: clamp(4px, 0.6vh, 8px);
            background: rgba(255, 255, 255, 0.05);
            border-radius: 4px;
            overflow: hidden;
            min-width: 60px;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
            background: linear-gradient(90deg, var(--accent-cyan), rgba(0, 229, 255, 0.6));
            transition: width 1s var(--ease-out-expo);
        }

        .slide.visible .bar-fill { width: var(--bar-width); }

        /* Highlight callout */
        .callout-row {
            background: rgba(255, 107, 53, 0.05) !important;
            border-left: 2px solid var(--accent-orange);
        }

        /* ===========================================
           SLIDE 3: MARKET SHARE PIE CHART
           =========================================== */
        .chart-layout {
            display: flex;
            gap: clamp(1rem, 3vw, 3rem);
            align-items: center;
            width: 100%;
            max-width: 1100px;
        }

        .chart-left {
            flex: 0 0 clamp(200px, 35vw, 380px);
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .chart-right {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vw, 0.6rem);
        }

        .pie-container {
            position: relative;
            width: clamp(180px, 30vw, 340px);
            height: clamp(180px, 30vw, 340px);
        }

        .pie-svg {
            width: 100%;
            height: 100%;
        }

        .pie-legend {
            display: flex;
            flex-direction: column;
            gap: clamp(0.2rem, 0.5vw, 0.4rem);
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.6vw, 0.5rem);
            font-size: var(--data-size);
        }

        .legend-dot {
            width: clamp(8px, 0.8vw, 12px);
            height: clamp(8px, 0.8vw, 12px);
            border-radius: 2px;
            flex-shrink: 0;
        }

        .legend-name { color: var(--text-secondary); flex: 1; }
        .legend-value { font-family: var(--font-mono); font-weight: 600; color: var(--text-primary); }

        .chart-highlight {
            margin-top: clamp(0.3rem, 1vw, 0.8rem);
            padding: clamp(0.3rem, 0.8vw, 0.6rem) clamp(0.5rem, 1.2vw, 1rem);
            background: rgba(255, 107, 53, 0.08);
            border-left: 3px solid var(--accent-orange);
            border-radius: 0 4px 4px 0;
            font-size: var(--small-size);
            color: var(--accent-orange);
            font-weight: 600;
        }

        /* ===========================================
           SLIDE 4: MARKET SHIFTS
           =========================================== */
        .insights-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: clamp(0.5rem, 1.5vw, 1.2rem);
            width: 100%;
            max-width: 1100px;
        }

        .insight-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1.2rem);
            transition: border-color 0.3s, transform 0.3s;
        }

        .insight-card:hover {
            border-color: var(--border-accent);
            transform: translateY(-2px);
        }

        .insight-icon {
            font-size: clamp(1rem, 2vw, 1.5rem);
            margin-bottom: clamp(0.2rem, 0.5vw, 0.4rem);
        }

        .insight-title {
            font-family: var(--font-display);
            font-size: clamp(0.7rem, 1.3vw, 1rem);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: clamp(0.15rem, 0.4vw, 0.3rem);
        }

        .insight-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .insight-stat {
            font-family: var(--font-mono);
            font-size: clamp(0.9rem, 2vw, 1.5rem);
            font-weight: 700;
            margin-bottom: clamp(0.1rem, 0.3vw, 0.2rem);
        }

        .stat-cyan { color: var(--accent-cyan); }
        .stat-orange { color: var(--accent-orange); }
        .stat-green { color: var(--accent-green); }
        .stat-pink { color: var(--accent-pink); }

        /* Trend chart mockup */
        .trend-chart {
            display: flex;
            align-items: flex-end;
            gap: 2px;
            height: clamp(40px, 8vh, 80px);
            margin-top: clamp(0.3rem, 0.8vw, 0.5rem);
        }

        .trend-bar {
            flex: 1;
            background: linear-gradient(to top, var(--accent-cyan), rgba(0, 229, 255, 0.3));
            border-radius: 2px 2px 0 0;
            transition: height 0.8s var(--ease-out-expo);
        }

        /* ===========================================
           SLIDE 5: RISING STARS
           =========================================== */
        .growth-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vw, 0.6rem);
            width: 100%;
            max-width: 1000px;
        }

        .growth-row {
            display: flex;
            align-items: center;
            gap: clamp(0.4rem, 1vw, 0.8rem);
        }

        .growth-model {
            flex: 0 0 clamp(100px, 18vw, 180px);
            font-size: clamp(0.55rem, 0.9vw, 0.8rem);
            font-weight: 600;
            color: var(--text-primary);
        }

        .growth-provider {
            flex: 0 0 clamp(70px, 12vw, 130px);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .growth-bar-bg {
            flex: 1;
            height: clamp(16px, 2.5vh, 28px);
            background: rgba(255, 255, 255, 0.03);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .growth-bar-fill {
            height: 100%;
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: flex-end;
            padding-right: clamp(0.3rem, 0.6vw, 0.5rem);
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.7vw, 0.6rem);
            font-weight: 700;
            color: var(--bg-primary);
            transition: width 1s var(--ease-out-expo);
        }

        .slide.visible .growth-bar-fill { width: var(--bar-width); }

        .growth-bar-fill.bar-green { background: linear-gradient(90deg, rgba(118, 255, 3, 0.3), var(--accent-green)); }
        .growth-bar-fill.bar-cyan { background: linear-gradient(90deg, rgba(0, 229, 255, 0.3), var(--accent-cyan)); }
        .growth-bar-fill.bar-orange { background: linear-gradient(90deg, rgba(255, 107, 53, 0.3), var(--accent-orange)); }

        .growth-label {
            flex: 0 0 clamp(45px, 7vw, 70px);
            font-family: var(--font-mono);
            font-size: clamp(0.55rem, 0.9vw, 0.75rem);
            font-weight: 700;
            text-align: right;
        }

        /* ===========================================
           SLIDE 6: APP ECOSYSTEM
           =========================================== */
        .app-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.4rem, 1vw, 0.8rem);
            width: 100%;
            max-width: 1100px;
        }

        .app-card {
            display: flex;
            align-items: center;
            gap: clamp(0.4rem, 1vw, 0.8rem);
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 6px;
            padding: clamp(0.4rem, 1vw, 0.8rem) clamp(0.5rem, 1.2vw, 1rem);
            transition: border-color 0.3s;
        }

        .app-card:hover { border-color: var(--border-accent); }

        .app-rank {
            font-family: var(--font-mono);
            font-size: clamp(0.7rem, 1.2vw, 1rem);
            font-weight: 700;
            color: var(--accent-cyan);
            flex-shrink: 0;
            width: clamp(20px, 2.5vw, 30px);
        }

        .app-rank.top { color: var(--accent-orange); }

        .app-info { flex: 1; min-width: 0; }

        .app-name {
            font-size: clamp(0.55rem, 0.9vw, 0.8rem);
            font-weight: 600;
            color: var(--text-primary);
        }

        .app-desc {
            font-size: clamp(0.45rem, 0.65vw, 0.6rem);
            color: var(--text-muted);
        }

        .app-volume {
            font-family: var(--font-mono);
            font-size: clamp(0.55rem, 0.9vw, 0.75rem);
            font-weight: 700;
            color: var(--accent-cyan);
            flex-shrink: 0;
        }

        .app-coding-tag {
            display: inline-block;
            font-size: clamp(0.4rem, 0.55vw, 0.5rem);
            background: rgba(118, 255, 3, 0.1);
            color: var(--accent-green);
            padding: 1px 4px;
            border-radius: 3px;
            margin-left: 4px;
        }

        /* ===========================================
           SLIDE 7: TAKEAWAYS
           =========================================== */
        .takeaway-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
