    <script>
        /* ===========================================
           PIE CHART GENERATION
           =========================================== */
        function createPieChart() {
            const data = [
                { name: 'Xiaomi', value: 25.9, color: '#00e5ff' },
                { name: 'Google', value: 11.8, color: '#4285f4' },
                { name: 'Anthropic', value: 11.0, color: '#d4a574' },
                { name: 'MiniMax', value: 8.5, color: '#7c4dff' },
                { name: 'OpenAI', value: 7.9, color: '#76ff03' },
                { name: 'Stepfun', value: 6.8, color: '#ff6b35' },
                { name: 'DeepSeek', value: 6.6, color: '#ff4081' },
                { name: 'Zhipu (z-ai)', value: 6.5, color: '#ffd740' },
                { name: 'x-ai', value: 3.9, color: '#8d6e63' },
                { name: 'Others', value: 11.2, color: '#546e7a' }
            ];

            const container = document.getElementById('pieChart');
            const size = container.clientWidth || 300;
            const cx = size / 2;
            const cy = size / 2;
            const r = size / 2 - 10;
            const innerR = r * 0.55;

            const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('viewBox', `0 0 ${size} ${size}`);
            svg.classList.add('pie-svg');

            let cumulativeAngle = -90;

            data.forEach((item, i) => {
                const angle = (item.value / 100) * 360;
                const startAngle = cumulativeAngle;
                const endAngle = cumulativeAngle + angle;

                const startRad = (startAngle * Math.PI) / 180;
                const endRad = (endAngle * Math.PI) / 180;

                const x1 = cx + r * Math.cos(startRad);
                const y1 = cy + r * Math.sin(startRad);
                const x2 = cx + r * Math.cos(endRad);
                const y2 = cy + r * Math.sin(endRad);

                const ix1 = cx + innerR * Math.cos(startRad);
                const iy1 = cy + innerR * Math.sin(startRad);
                const ix2 = cx + innerR * Math.cos(endRad);
                const iy2 = cy + innerR * Math.sin(endRad);

                const largeArc = angle > 180 ? 1 : 0;

                const d = `M ${ix1} ${iy1} L ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2} L ${ix2} ${iy2} A ${innerR} ${innerR} 0 ${largeArc} 0 ${ix1} ${iy1} Z`;

                const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                path.setAttribute('d', d);
                path.setAttribute('fill', item.color);
                path.setAttribute('stroke', '#0a0f1c');
                path.setAttribute('stroke-width', '2');
                path.style.transition = `opacity 0.5s ease ${i * 0.08}s, transform 0.5s ease ${i * 0.08}s`;
                path.style.opacity = '0';
                svg.appendChild(path);

                setTimeout(() => { path.style.opacity = '1'; }, 300 + i * 80);

                cumulativeAngle = endAngle;
            });

            // Center text
            const text1 = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            text1.setAttribute('x', cx);
            text1.setAttribute('y', cy - 8);
            text1.setAttribute('text-anchor', 'middle');
            text1.setAttribute('fill', '#f0f0f0');
            text1.setAttribute('font-family', 'JetBrains Mono, monospace');
            text1.setAttribute('font-size', size * 0.08);
            text1.setAttribute('font-weight', '700');
            text1.textContent = '25.9%';
            svg.appendChild(text1);

            const text2 = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            text2.setAttribute('x', cx);
            text2.setAttribute('y', cy + size * 0.06);
            text2.setAttribute('text-anchor', 'middle');
            text2.setAttribute('fill', '#9ca3af');
            text2.setAttribute('font-family', 'DM Sans, sans-serif');
            text2.setAttribute('font-size', size * 0.04);
            text2.textContent = 'Xiaomi leads';
            svg.appendChild(text2);

            container.appendChild(svg);

            // Legend
            const legend = document.getElementById('pieLegend');
            data.forEach(item => {
                const el = document.createElement('div');
                el.className = 'legend-item';
                el.innerHTML = `
                    <span class="legend-dot" style="background: ${item.color}"></span>
                    <span class="legend-name">${item.name}</span>
                    <span class="legend-value">${item.value}%</span>
                `;
                legend.appendChild(el);
            });
        }

        /* ===========================================
           TREND CHART (Mini bar chart for Slide 4)
           =========================================== */
        function createTrendChart() {
            const container = document.getElementById('trendChart');
            const heights = [8, 12, 18, 25, 32, 38, 45, 52, 60, 68, 78, 100];
            heights.forEach((h, i) => {
                const bar = document.createElement('div');
                bar.className = 'trend-bar';
                bar.style.height = '0%';
                container.appendChild(bar);
                setTimeout(() => { bar.style.height = h + '%'; }, 600 + i * 60);
            });
        }

        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isScrolling = false;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const idx = [...this.slides].indexOf(entry.target);
                            if (idx !== -1) {
                                this.currentSlide = idx;
                                this.updateNavDots();
                                this.updateProgressBar();
                            }
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            goToSlide(index) {
                if (index < 0 || index >= this.slides.length) return;
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
                this.currentSlide = index;
                this.updateNavDots();
                this.updateProgressBar();
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
