const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

const HTML_PATH = process.argv[2];
const OUT_DIR = process.argv[3];
const WIDTH = parseInt(process.argv[4]) || 1920;
const HEIGHT = parseInt(process.argv[5]) || 1080;

(async () => {
    const browser = await chromium.launch({
        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined
    });
    const page = await browser.newPage();
    await page.setViewportSize({ width: WIDTH, height: HEIGHT });

    const fileUrl = 'file://' + HTML_PATH;
    await page.goto(fileUrl, { waitUntil: 'networkidle' });

    // Wait for fonts and initial render
    await page.waitForTimeout(2000);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log(`Found ${slideCount} slides`);

    // Capture each slide by scrolling to it
    for (let i = 0; i < slideCount; i++) {
        // Scroll slide into view using evaluate
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].scrollIntoView({ behavior: 'instant' });
                slides[idx].classList.add('visible');
            }
        }, i);

        // Wait for animations to settle
        await page.waitForTimeout(800);

        const idx = String(i + 1).padStart(3, '0');
        const screenshotPath = path.join(OUT_DIR, `slide_${idx}.png`);
        await page.screenshot({ path: screenshotPath });
        console.log(`Captured slide ${i + 1}`);
    }

    console.log(`Done: ${slideCount} slides captured`);
    await browser.close();
})();

